class Main {
    static class Base {
        static int shared;
        int read() { return shared; }
    }
    static class Child extends Base {
        // 실제 Child 객체의 메서드가 실행돼요.
        int read() { return shared + 10; }
    }

    public static void main(String[] args) {
        // 이번 실험의 시작값이에요.
        int n = 3;
        Base.shared = n;
        Base ref = new Child();
        // 부모를 새로 만들지 않고 준비된 객체를 호출해요.
        System.out.println(new Base().read());
    }
}
